import json, pathlib, sys
root = pathlib.Path(".")
needles = ["#3d63dd", "#3D63DD", "61, 99, 221", "61,99,221", "#2f4fb8"]
bad = []
for path in root.joinpath("src").rglob("*"):
    if path.suffix.lower() not in {".css", ".tsx", ".ts"}:
        continue
    text = path.read_text(encoding="utf-8")
    for needle in needles:
        if needle in text:
            bad.append(f"{path}: {needle}")
pkg = json.loads(root.joinpath("package.json").read_text(encoding="utf-8"))
blob = json.dumps(pkg)
if "lucide-react" in blob:
    bad.append("package.json contains lucide-react")
css = root.joinpath("src/shell/shell.css").read_text(encoding="utf-8")
if "translateY(-1.5px)" not in css:
    bad.append("title nudge missing")
if pkg.get("name") != "emerge":
    bad.append(f"package name is {pkg.get(\"name\")}")
conf = root.joinpath("src-tauri/tauri.conf.json").read_text(encoding="utf-8")
if "\"identifier\": \"local.emerge.app\"" not in conf:
    bad.append("bundle identifier changed")
tokens = root.joinpath("src/shell/tokens.css").read_text(encoding="utf-8")
handoff = pathlib.Path("/tmp/aperio-v11/design_handoff_aperio/tokens.css").read_text(encoding="utf-8")
if tokens != handoff:
    bad.append("tokens.css differs from v1.1")
if bad:
    print("\n".join(bad))
    sys.exit(1)
print("old accent gone; tokens match; no lucide; title nudge kept; name and identifier kept")
